  --bg-card-inner-subtle: rgba(15, 23, 42, 0.4);
  --bg-table-th: #0f172a;
  --table-th-solid: #0f172a;
  --text-th: #94a3b8;
  --bg-table-row-even: rgba(255, 255, 255, 0.02);
  --bg-table-row-hover: rgba(51, 65, 85, 0.4);
  --table-row-odd-solid: #0d1527;
