  --bg-sidebar: #0f172a;
  --bg-sidebar-header: rgba(15, 23, 42, 0.9);
  --bg-sidebar-btn: rgba(30, 41, 59, 0.65);
  --bg-sidebar-btn-hover: rgba(30, 41, 59, 0.95);
  --border-color: rgba(255, 255, 255, 0.12);
  --border-color-subtle: rgba(255, 255, 255, 0.06);
  --text-main: #cbd5e1;
  --text-title: #f8fafc;
  --text-primary: #cbd5e1;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --accent-blue: #38bdf8;
  --accent-purple: #818cf8;
  --accent-color: #38bdf8;
  --accent-gradient: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  --color-accent-blue: #38bdf8;
  --color-accent-gold: #fbbf24;
  --color-accent-green: #34d399;
  --color-accent-rose: #f472b6;
  --color-accent-purple: #c084fc;
  --badge-special-bg: rgba(56, 189, 248, 0.12);
  --badge-special-border: rgba(56, 189, 248, 0.5);
  --badge-special-text: #7dd3fc;

  /* Recipe Badges Tokens (Midnight Dark) */
  --badge-cat-curry-bg: rgba(245, 158, 11, 0.2);
  --badge-cat-curry-text: #fbbf24;
  --badge-cat-curry-border: rgba(245, 158, 11, 0.4);

  --badge-cat-salad-bg: rgba(34, 197, 94, 0.2);
  --badge-cat-salad-text: #4ade80;
