  --badge-cat-dessert-bg: rgba(236, 72, 153, 0.2);
  --badge-cat-dessert-text: #f472b6;
  --badge-cat-dessert-border: rgba(236, 72, 153, 0.4);

  --badge-pot-bg: rgba(56, 189, 248, 0.15);
  --badge-pot-text: #38bdf8;
  --badge-pot-border: rgba(56, 189, 248, 0.35);

  --badge-bonus-78-bg: rgba(251, 191, 36, 0.25);
  --badge-bonus-78-text: #fbbf24;
  --badge-bonus-78-border: rgba(251, 191, 36, 0.7);

  --badge-bonus-61-bg: rgba(239, 68, 68, 0.2);
  --badge-bonus-61-text: #f87171;
  --badge-bonus-61-border: rgba(239, 68, 68, 0.5);

  --badge-bonus-48-bg: rgba(168, 85, 247, 0.2);
  --badge-bonus-48-text: #c084fc;
  --badge-bonus-48-border: rgba(168, 85, 247, 0.5);

  --badge-bonus-35-bg: rgba(59, 130, 246, 0.2);
  --badge-bonus-35-text: #60a5fa;
  --badge-bonus-35-border: rgba(59, 130, 246, 0.5);

  --badge-bonus-25-bg: rgba(16, 185, 129, 0.2);
  --badge-bonus-25-text: #34d399;
  --badge-bonus-25-border: rgba(16, 185, 129, 0.5);

  --badge-bonus-default-bg: rgba(255, 255, 255, 0.08);
  --badge-bonus-default-text: var(--text-main);
  --badge-bonus-default-border: rgba(255, 255, 255, 0.15);

  /* Ladder 3-Meal Passing Line Tokens (Midnight Dark) */
  --ladder-passing-line-color: #f59e0b;
  --ladder-passing-line-glow: rgba(245, 158, 11, 0.55);
  --ladder-passing-badge-bg: rgba(26, 21, 12, 0.94);
