  --shadow-lg: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 20px 35px -5px rgba(0, 0, 0, 0.6), 0 0 15px rgba(56, 189, 248, 0.2);
  --bg-radial-1: rgba(56, 189, 248, 0.15);
  --bg-radial-2: rgba(129, 140, 248, 0.15);
  --bg-radial-3: rgba(10, 15, 29, 0.95);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;

  /* Type Colors */
  --type-草: #4ad071;
  --type-火: #fb6c6c;
  --type-水: #76befe;
  --type-蟲: #92dc3d;
  --type-一般: #a8a878;
  --type-毒: #aa45a0;
  --type-電: #ffd833;
  --type-妖: #f49ba8;
  --type-妖精: #f49ba8;
  --type-冰: #7cd8c1;
  --type-地: #e0c068;
  --type-地面: #e0c068;
  --type-鬥: #c03028;
  --type-格鬥: #c03028;
  --type-岩: #b8a038;
  --type-岩石: #b8a038;
  --type-惡: #705848;
  --type-鋼: #b8b8d0;
  --type-飛: #a890f0;
  --type-飛行: #a890f0;
  --type-鬼: #70559b;
  --type-幽靈: #70559b;
  --type-超: #f85888;
  --type-超能力: #f85888;
  --type-龍: #7038f8;
