* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  background-color: var(--bg-dark);
}

body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  background-color: var(--bg-dark);
  background-image: 
    radial-gradient(at 0% 0%, var(--bg-radial-1) 0px, transparent 50%),
    radial-gradient(at 100% 0%, var(--bg-radial-2) 0px, transparent 50%),
    radial-gradient(at 50% 100%, var(--bg-radial-3) 0px, transparent 50%);
  background-attachment: fixed;
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Header */
header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-color);
  height: 70px;
  padding: 0;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 100;
  box-sizing: border-box;
}

.header-container {
  width: 100%;
  max-width: 100%;
  height: 100%;
  margin: 0;
  padding: 0 28px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  box-sizing: border-box;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  justify-self: start;
}

.brand-logo {
  width: 40px;
  height: 40px;
  background: var(--accent-gradient);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  box-shadow: 0 4px 12px rgba(56, 189, 248, 0.3);
}

.brand-title {
  font-size: 19px;
  font-weight: 700;
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.3px;
}

.brand-subtitle {
  font-size: 12px;
  color: var(--text-secondary);
}

/* 英文模式下隱藏 subtitle 並確保標題上下垂直置中 (English Mode Subtitle Hiding & Centering) */
html[lang="en"] .brand-subtitle,
[data-lang="en"] .brand-subtitle,
html[lang="en"] .pokemon-name-en,
[data-lang="en"] .pokemon-name-en,
html[lang="en"] .recipe-name-sub,
[data-lang="en"] .recipe-name-sub,
html[lang="en"] .appraisal-pokemon-en,
[data-lang="en"] .appraisal-pokemon-en {
  display: none !important;
}

html[lang="en"] .brand,
[data-lang="en"] .brand {
  align-items: center;
}

html[lang="en"] .card-title-group,
[data-lang="en"] .card-title-group {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

html[lang="en"] .pokemon-name-cell,
[data-lang="en"] .pokemon-name-cell {
  vertical-align: middle !important;
}

html[lang="en"] .appraisal-pokemon-title,
[data-lang="en"] .appraisal-pokemon-title {
  display: flex;
  align-items: center;
}

/* 英文模式彈窗標籤與文字排版適配 (English Mode Modal Layout Adaptation) */
html[data-lang="en"] .box-modal-dialog,
[data-lang="en"] .box-modal-dialog {
