  width: 90px;
}

/* SPA Main Navigation Tabs */
.main-tab-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  justify-self: center;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 4px;
  gap: 4px;
  box-shadow: var(--shadow-sm, 0 4px 16px rgba(0, 0, 0, 0.15));
}

.main-tab-toggle .toggle-btn {
  padding: 7px 18px;
  border-radius: 8px; /* 12px (outer) - 4px (padding) = 8px (inner) concentric alignment */
  font-size: 13px;
  font-weight: 700;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  user-select: none;
}

.main-tab-toggle .toggle-btn:hover {
  color: var(--text-primary);
  background: var(--bg-card-hover);
}

.main-tab-toggle .toggle-btn.active {
  background: var(--accent-gradient);
  color: #ffffff;
  border-radius: 8px;
  box-shadow: 0 2px 10px rgba(56, 189, 248, 0.35);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  justify-self: end;
}

.sync-wrapper {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.sync-btn {
  padding: 7px 14px;
  background: var(--accent-gradient);
  border: none;
  border-radius: 10px;
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(74, 222, 128, 0.3);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
  white-space: nowrap;
}

.sync-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(74, 222, 128, 0.4);
}

.sync-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.sync-status {
  font-size: 12px;
  color: var(--text-secondary);
  max-width: 300px;
  text-align: right;
}

