  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.empty-icon {
  font-size: 48px;
  margin-bottom: 8px;
}

.empty-state-banner h3 {
  font-size: 18px;
  color: var(--text-primary);
}

.empty-state-banner p {
  font-size: 14px;
  color: var(--text-muted);
  max-width: 360px;
}

.reset-filters-btn {
  margin-top: 12px;
  padding: 8px 20px;
  background: var(--accent-gradient);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.reset-filters-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(56, 189, 248, 0.3);
}

.loading-state {
  text-align: center;
  padding: 60px;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.spinner {
  width: 36px;
  height: 36px;
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-top-color: var(--accent-color);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

/* ───  App 風格全域中央載入元件 (App Loading View & Spinner) ─── */
.app-loading-view,
.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 240px;
  width: 100%;
  padding: 40px 20px;
  gap: 14px;
  box-sizing: border-box;
  text-align: center;
}

.app-loading-spinner,
.loading-spinner {
  width: 38px;
  height: 38px;
  border: 3.5px solid rgba(56, 189, 248, 0.18);
  border-top-color: var(--accent-blue, #38bdf8);
  border-right-color: var(--accent-blue, #38bdf8);
  border-radius: 50%;
  animation: app-spin 0.8s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
  box-shadow: 0 0 16px var(--accent-glow, rgba(56, 189, 248, 0.25));
}

@keyframes app-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.app-loading-text {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: 0.3px;
  animation: app-pulse-text 1.5s ease-in-out infinite;
}

@keyframes app-pulse-text {
  0%, 100% { opacity: 0.65; }
  50% { opacity: 1; }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Footer */
footer {
  display: none !important;
  max-width: 1200px;
  width: 92%;
  margin: 40px auto 0;
  padding: 28px 16px;
  text-align: center;
  border-top: 1px solid var(--border-color);
  color: var(--text-muted);
  font-size: 13px;
}

/* Recipe Badge & Category Styles */
.recipe-cat-badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.recipe-cat-badge.cat-咖哩 {
  background: var(--badge-cat-curry-bg);
  color: var(--badge-cat-curry-text);
  border: 1px solid var(--badge-cat-curry-border);
}

.recipe-cat-badge.cat-沙拉 {
  background: var(--badge-cat-salad-bg);
  color: var(--badge-cat-salad-text);
  border: 1px solid var(--badge-cat-salad-border);
}

.recipe-cat-badge.cat-甜點 {
  background: var(--badge-cat-dessert-bg);
  color: var(--badge-cat-dessert-text);
  border: 1px solid var(--badge-cat-dessert-border);
}

.pot-badge {
  background: var(--badge-pot-bg);
  color: var(--badge-pot-text);
  border: 1px solid var(--badge-pot-border);
  padding: 4px 10px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 700;
  font-family: monospace;
  white-space: nowrap;
}

/* Bonus badge */
.bonus-badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  background: var(--badge-bonus-default-bg);
  color: var(--badge-bonus-default-text);
  border: 1px solid var(--badge-bonus-default-border);
}

.bonus-badge.bonus-badge-78 {
  background: var(--badge-bonus-78-bg);
  color: var(--badge-bonus-78-text);
  border: 1px solid var(--badge-bonus-78-border);
}

.bonus-badge.bonus-badge-61 {
  background: var(--badge-bonus-61-bg);
  color: var(--badge-bonus-61-text);
  border: 1px solid var(--badge-bonus-61-border);
}

.bonus-badge.bonus-badge-48 {
  background: var(--badge-bonus-48-bg);
  color: var(--badge-bonus-48-text);
  border: 1px solid var(--badge-bonus-48-border);
}

.bonus-badge.bonus-badge-35 {
  background: var(--badge-bonus-35-bg);
  color: var(--badge-bonus-35-text);
  border: 1px solid var(--badge-bonus-35-border);
}

.bonus-badge.bonus-badge-25 {
  background: var(--badge-bonus-25-bg);
  color: var(--badge-bonus-25-text);
  border: 1px solid var(--badge-bonus-25-border);
}

.bonus-badge.bonus-badge-default {
  background: var(--badge-bonus-default-bg);
  color: var(--badge-bonus-default-text);
  border: 1px solid var(--badge-bonus-default-border);
}

.recipe-name-cell {
  vertical-align: middle !important;
}

.recipe-name-wrapper {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 52px;
}

html[lang="en"] .recipe-name-wrapper,
[data-lang="en"] .recipe-name-wrapper {
  justify-content: center;
}

/* Bonus filter active states */
.bonus-filter-btn.active {
  background: var(--accent-gradient);
  color: #ffffff;
  border-color: transparent;
  box-shadow: 0 2px 8px rgba(56, 189, 248, 0.35);
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}

.ing-badge {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  padding: 6px 8px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-color);
