  top: -5px;
  right: -5px;
  width: 14px;
  height: 14px;
  background: #ef4444;
  color: #fff;
  font-size: 9px;
  font-weight: 900;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.ing-picker-icon {
  width: 28px;
  height: 28px;
  object-fit: contain;
  flex-shrink: 0;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.5));
}

/* ─── Raenonx-style filter bar ──────────────────────── */
.raenonx-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: flex-start;
  padding: 16px 20px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  margin-bottom: 8px;
}

.recipe-layout-view,
.box-layout-view {
  position: relative;
  width: 100%;
}

.recipe-main-content,
.box-main-content {
  width: 100%;
  margin: 0 auto;
  min-height: calc(100vh - 120px);
}

.recipe-main-content .controls-container,
.box-main-content .controls-container {
  max-width: 1200px;
  width: 92%;
  margin: 24px auto 16px;
  padding: 0 16px;
  box-sizing: border-box;
}

.recipe-main-content .stats-bar {
  max-width: 1200px;
  width: 92%;
  margin: 0 auto 16px;
  padding: 0 16px;
  box-sizing: border-box;
}

body:not(.mobile-h5-app) .recipe-main-content #recipe-content-area {
  max-width: 1200px;
  width: 92%;
  margin: 0 auto 40px;
  padding: 0 16px;
  box-sizing: border-box;
}

body:not(.mobile-h5-app) .recipe-main-content #recipe-content-area .pokemon-grid,
body:not(.mobile-h5-app) .recipe-main-content #recipe-content-area .recipe-cards-grid {
