  width: 100%;
  margin: 0 auto 16px;
  padding: 0;
}

body:not(.mobile-h5-app) .recipe-main-content #recipe-content-area .table-container,
body:not(.mobile-h5-app) .recipe-main-content #recipe-content-area .pokemon-table-container {
