}

#recipe-content-area {
  width: 100%;
}

/*  桌面版料理卡片緊湊排版 (Desktop Recipe Cards) */
.recipe-desktop-card {
  padding: 10px 12px !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
}

.recipe-desktop-stats {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color-subtle, var(--border-color));
  border-radius: var(--radius-md, 8px);
  padding: 6px 10px;
}

.recipe-stat-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  font-size: 12.5px;
}

.recipe-stat-row .stat-label {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
}

.recipe-stat-row .stat-value.pot-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-blue);
  font-family: monospace, -apple-system;
}

.recipe-stat-row .stat-value.energy-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-accent-gold, #f59e0b);
  font-family: monospace, -apple-system;
}

/* 桌面版食譜預估能量 3 階垂直排列 (Desktop 3-Stack Energy Rows: 1x / 2x / 3x) */
.recipe-table th[data-sort="energy"],
.recipe-table th.th-energy {
  font-size: 14px !important;
  padding-right: 32px !important;
}

.recipe-table th.th-energy .table-sub-header {
  font-size: 11px;
  font-weight: 400;
  color: var(--text-muted);
  margin-top: 2px;
}

.recipe-table td.recipe-energy-cell {
  padding-right: 32px !important;
}

.desktop-energy-stack {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
  min-width: 110px;
}

.desktop-energy-stack.has-tasty {
  padding: 1px 0;
}

.desktop-energy-row {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 5px;
  width: 100%;
  line-height: 1.25;
}

.desktop-energy-row .energy-multiplier {
  font-size: 12px;
  font-weight: 700;
  font-family: monospace, -apple-system, sans-serif;
  opacity: 0.85;
  width: 18px;
  text-align: left;
  flex-shrink: 0;
}

.desktop-energy-row .energy-number {
  font-size: 15.5px;
  font-weight: 700;
  font-family: monospace, -apple-system, sans-serif;
  white-space: nowrap;
  text-align: right;
  flex: 1;
}

.desktop-energy-stack.single-energy .desktop-energy-row .energy-number {
  font-size: 16px;
  font-weight: 700;
}

.desktop-energy-stack.has-tasty .desktop-energy-row .energy-number {
  font-size: 15px;
  font-weight: 700;
}

/* 1x: 主文字色 (柔和白/灰/黑) */
.desktop-energy-row.energy-1x {
  color: var(--text-primary);
}

/* 2x: 蔚藍/天藍色高亮 */
.desktop-energy-row.energy-2x {
  color: #38bdf8;
}

[data-theme="dawn"] .desktop-energy-row.energy-2x,
[data-theme="emerald"] .desktop-energy-row.energy-2x {
  color: #0284c7;
}

/* 3x: 琥珀金橘色高亮 */
.desktop-energy-row.energy-3x {
  color: #fbbf24;
}

[data-theme="dawn"] .desktop-energy-row.energy-3x,
[data-theme="emerald"] .desktop-energy-row.energy-3x {
  color: #d97706;
}

.tasty-stats-row {
  padding-top: 4px;
  border-top: 1px dashed var(--border-color);
  margin-top: 2px;
  gap: 6px;
}

.tasty-desktop-badge {
  font-size: 11px;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.1);
  padding: 2px 6px;
  border-radius: 4px;
  font-family: monospace, -apple-system;
}

.tasty-desktop-badge.tasty-3x {
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}

.recipe-desktop-ings {
  width: 100%;
  margin-top: 2px;
}

.compact-4-row {
  display: flex !important;
  flex-wrap: nowrap !important;
  gap: 4px !important;
  width: 100% !important;
  overflow-x: auto !important;
  scrollbar-width: none !important;
}

.compact-4-row::-webkit-scrollbar {
  display: none !important;
}

.compact-chip {
  display: inline-flex !important;
  align-items: center !important;
  gap: 2.5px !important;
  padding: 2px 5px !important;
  border-radius: 6px !important;
  background: var(--bg-card-inner) !important;
  border: 1px solid var(--border-color) !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  color: var(--text-secondary) !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}

.compact-chip .recipe-ing-icon {
  width: 16px !important;
  height: 16px !important;
  object-fit: contain !important;
}

/* 料理種類 2 欄網格 */
.sidebar-2col-tags {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 4px;
  width: 100%;
}

/* 食譜側邊欄食材圖標按鈕（7 列自適應網格，對齊圖鑑樣式） */
.sidebar-icon-grid .ing-picker-btn {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  aspect-ratio: 1 / 1 !important;
  height: auto !important;
  background: var(--bg-sidebar-btn) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: 6px !important;
  cursor: pointer !important;
  padding: 2px !important;
  margin: 0 !important;
  box-sizing: border-box !important;
  transition: border-color 0.15s ease, background-color 0.15s ease !important;
}

.sidebar-icon-grid .ing-picker-btn:hover {
  background: var(--bg-sidebar-btn-hover) !important;
  border-color: rgba(56, 189, 248, 0.4) !important;
}

.sidebar-icon-grid .ing-picker-btn.active {
  background: #0284c7 !important;
  border-color: #38bdf8 !important;
}

.sidebar-icon-grid .ing-picker-btn.active-exclude {
  background: rgba(239, 68, 68, 0.2) !important;
  border-color: #ef4444 !important;
}

.sidebar-icon-grid .ing-picker-btn .ing-picker-icon {
  width: 100% !important;
  height: 100% !important;
  max-width: 22px !important;
  max-height: 22px !important;
  object-fit: contain !important;
  pointer-events: none !important;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.4)) !important;
  flex-shrink: 1 !important;
}

/* 食譜側邊欄滑桿項目 */
.sidebar-slider-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-bottom: 8px;
}

.sidebar-slider-item .slider-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11.5px;
  color: var(--text-muted);
}

.sidebar-slider-item .slider-value-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.3);
  color: var(--color-accent-gold);
}

.sidebar-slider-item .island-bonus-badge {
  color: var(--color-accent-green);
  background: rgba(16, 185, 129, 0.15);
  border-color: rgba(16, 185, 129, 0.3);
}

.sidebar-slider-item .event-bonus-badge {
  color: #f472b6;
  background: rgba(244, 114, 182, 0.15);
  border-color: rgba(244, 114, 182, 0.3);
}

.sidebar-slider-item .slider-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sidebar-slider-item .slider-row span {
  font-size: 10px;
  color: var(--text-muted);
}

.sidebar-slider-item .rf-slider {
  flex: 1;
}

.recipe-filter-sidebar .rf-select-wrap .custom-select-container {
  width: 100%;
}

.recipe-filter-sidebar .rf-select-wrap .custom-select-trigger {
  padding: 5px 36px 5px 10px;
  font-size: 12px;
  background: var(--bg-sidebar-btn);
  border-radius: 5px;
}

.rf-select {
  display: none;
}

/* ─── 全域自訂下拉選單系統 (Custom Dropdown System) ────────────────────────── */
.custom-select-container {
  position: relative;
  display: inline-block;
  user-select: none;
}

.custom-select-sort {
  width: 100%;
}

.custom-select-rf {
  min-width: 110px;
}

.custom-select-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  cursor: pointer;
  outline: none;
  font-family: inherit;
  position: relative;
  transition: all 0.2s ease;
  box-sizing: border-box;
}

.custom-select-sort .custom-select-trigger {
  padding: 9px 42px 9px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 13.5px;
  font-weight: 500;
}

.custom-select-rf .custom-select-trigger {
  padding: 6px 38px 6px 10px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
}

.custom-select-trigger:hover,
.custom-select-container.open .custom-select-trigger {
  border-color: rgba(99, 102, 241, 0.6);
}

.custom-select-container.open .custom-select-trigger {
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

.custom-select-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.custom-select-label span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.custom-select-arrow {
  position: absolute;
  right: 14px; /* 保留充足寬鬆且精緻之視覺間距 (Rule VI) */
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  transition: transform 0.2s ease, color 0.2s ease;
}

.custom-select-arrow svg {
  width: 7px !important;
  height: 4.5px !important;
  display: block;
}

.custom-select-container.open .custom-select-arrow {
  transform: translateY(-50%) rotate(180deg);
  color: #818cf8;
}

/* 下拉選單選單面板：嚴格位於下方正對展開，並與選擇框底部對齊 */
.custom-select-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  min-width: 100%;
  width: max-content;
  max-width: 420px;
  max-height: 260px;
  overflow-y: auto;
  background: var(--bg-card-solid);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  box-shadow: var(--shadow-lg);
  backdrop-filter: blur(12px);
  z-index: 1000;
  padding: 4px;
  display: none;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 0.15s ease, transform 0.15s ease;
  box-sizing: border-box;
}

.custom-select-container.open .custom-select-menu {
  display: block;
  opacity: 1;
  transform: translateY(0);
}

.custom-select-item {
  padding: 8px 12px;
