}

.custom-select-check {
  font-size: 12px;
  color: var(--accent-color);
  font-weight: 700;
}

.custom-select-icon {
  width: 20px;
  height: 20px;
  object-fit: contain;
  flex-shrink: 0;
  vertical-align: middle;
}

.custom-select-item-content {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 1;
