/* ─── Recipe ingredient inline chips ─────────────────── */
.recipe-ing-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  align-items: center;
}

.pokemon-table .recipe-ing-row {
  justify-content: center;
}

.recipe-ing-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color-subtle);
  border-radius: 8px;
  padding: 3px 6px 3px 3px;
