}

/* ─── Level & Island Bonus Sliders ─────────────────────── */
.slider-filter-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 160px;
}

.slider-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.slider-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.slider-value-badge {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-accent-gold);
  background: rgba(245, 158, 11, 0.12);
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 8px;
  padding: 2px 10px;
  white-space: nowrap;
  min-width: 52px;
  text-align: center;
}

.island-bonus-badge {
  color: var(--color-accent-green);
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.event-bonus-badge {
  color: var(--color-accent-rose);
  background: rgba(244, 63, 94, 0.12);
  border: 1px solid rgba(244, 63, 94, 0.35);
}

.pot-expansion-badge {
  color: var(--accent-blue, #38bdf8);
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.35);
}

/* Range slider base */
input[type=range].rf-slider {
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  border-radius: 3px;
  background: var(--border-color);
  outline: none;
  cursor: pointer;
  flex: 1;
  transition: background 0.2s;
}

input[type=range].rf-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent-gold), #f59e0b);
  border: 2px solid rgba(255,255,255,0.8);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(245, 158, 11, 0.4);
  transition: transform 0.15s;
}

input[type=range].rf-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

input[type=range].rf-slider.island-slider::-webkit-slider-thumb {
  background: linear-gradient(135deg, var(--color-accent-green), #10b981);
  box-shadow: 0 2px 6px rgba(16,185,129,0.4);
}

input[type=range].rf-slider.event-slider::-webkit-slider-thumb {
  background: linear-gradient(135deg, var(--color-accent-rose), #f43f5e);
  box-shadow: 0 2px 6px rgba(244,63,94,0.4);
}

input[type=range].rf-slider.pot-slider::-webkit-slider-thumb {
  background: linear-gradient(135deg, var(--accent-blue, #38bdf8), #0284c7);
  box-shadow: 0 2px 6px rgba(56, 189, 248, 0.4);
}

input[type=range].rf-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-accent-gold), #f59e0b);
  border: 2px solid rgba(255,255,255,0.8);
  cursor: pointer;
}

/* Track fill */
input[type=range].rf-slider {
  background: linear-gradient(
    to right,
    rgba(245, 158, 11, 0.7) 0%,
    rgba(245, 158, 11, 0.7) var(--slider-fill, 0%),
    var(--border-color) var(--slider-fill, 0%),
    var(--border-color) 100%
  );
}

input[type=range].rf-slider.island-slider {
  background: linear-gradient(
    to right,
    rgba(16, 185, 129, 0.7) 0%,
    rgba(16, 185, 129, 0.7) var(--slider-fill, 0%),
    var(--border-color) var(--slider-fill, 0%),
    var(--border-color) 100%
  );
}

input[type=range].rf-slider.event-slider {
  background: linear-gradient(
    to right,
    rgba(244, 63, 94, 0.7) 0%,
    rgba(244, 63, 94, 0.7) var(--slider-fill, 0%),
    var(--border-color) var(--slider-fill, 0%),
    var(--border-color) 100%
  );
}

input[type=range].rf-slider.pot-slider {
  background: linear-gradient(
    to right,
    rgba(56, 189, 248, 0.7) 0%,
    rgba(56, 189, 248, 0.7) var(--slider-fill, 0%),
    var(--border-color) var(--slider-fill, 0%),
    var(--border-color) 100%
  );
}

/* ─── 漂亮成功分數 Switch Button 樣式 ─────────────────────────── */
.tasty-switch-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 8px 14px;
  border-radius: 12px;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.tasty-switch-btn:hover {
  border-color: rgba(236,72,153,0.45);
  background: var(--bg-card-hover);
}

.tasty-switch-btn.active {
  border-color: rgba(236,72,153,0.6);
  background: rgba(236,72,153,0.12);
  box-shadow: 0 0 14px rgba(236,72,153,0.2);
}

.tasty-switch-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.tasty-toggle-icon {
  font-size: 16px;
}

.tasty-toggle-text {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-main);
  white-space: nowrap;
}

/* Switch Track & Sliding Thumb */
.tasty-switch-track {
  display: inline-flex;
  align-items: center;
  width: 38px;
  height: 22px;
  background: var(--border-color);
  border-radius: 9999px;
  padding: 2px;
  transition: background 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  flex-shrink: 0;
  box-sizing: border-box;
}

.tasty-switch-thumb {
  display: block;
  width: 18px;
  height: 18px;
  background: #ffffff;
  border-radius: 50%;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
  transform: translateX(0);
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.25s ease;
}

.tasty-switch-btn.active .tasty-switch-track {
  background: linear-gradient(135deg, #ec4899, #f43f5e);
  box-shadow: 0 0 8px rgba(236, 72, 153, 0.5);
}

.tasty-switch-btn.active .tasty-switch-thumb {
  transform: translateX(16px);
}

/* ─── 漂亮分數垂直上下排列堆疊 (3欄精密格點對齊) ───────── */
.tasty-energy-stack {
  display: inline-flex;
  flex-direction: column;
  gap: 3px;
  align-items: stretch;
  margin: 0 auto;
  text-align: left;
}

.tasty-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 14.5px;
  font-weight: 700;
  line-height: 1.25;
  white-space: nowrap;
}

.tasty-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-main, sans-serif);
  font-size: 11px;
  font-weight: 700;
  padding: 1px 6px;
  height: 18px;
  border-radius: 4px;
  box-sizing: border-box;
  text-align: center;
}

.tasty-num {
  font-family: monospace;
  font-size: 14.5px;
  font-weight: 700;
  text-align: right;
  letter-spacing: 0.3px;
}

.tasty-row-normal {
  color: var(--color-accent-gold);
}
.tasty-row-normal .tasty-tag {
  background: rgba(245, 158, 11, 0.15);
  color: var(--color-accent-gold);
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.tasty-row-2x {
  color: var(--color-accent-rose);
}
.tasty-row-2x .tasty-tag {
  background: rgba(244, 114, 182, 0.15);
  color: var(--color-accent-rose);
  border: 1px solid rgba(244, 114, 182, 0.3);
}

.tasty-row-3x {
  color: var(--color-accent-purple);
}
.tasty-row-3x .tasty-tag {
  background: rgba(192, 132, 252, 0.15);
  color: var(--color-accent-purple);
  border: 1px solid rgba(192, 132, 252, 0.3);
}

/* 卡片視圖中的漂亮分數 */
.card-tasty-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: monospace;
  margin-top: 6px;
  padding-top: 6px;
