}
.card-score-2x {
  color: #f472b6;
  font-weight: 700;
  font-size: 14.5px;
}
.card-score-3x {
  color: #c084fc;
  font-weight: 700;
  font-size: 14.5px;
}

/* RF group vertical variant */
.rf-group-vertical {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 200px;
  flex: 1;
}

.rf-group-vertical .rf-label {
  margin-bottom: 0;
}

