/* 二級子分頁切換按鈕 */
.wiki-subnav-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  border-top: none;
  padding-top: 0;
  align-items: center;
}

.wiki-subtab-btn {
  padding: 5px 11px;
