}

/* 篩選按鈕列 */
.wiki-control-bar {
  margin-bottom: 20px;
}

.wiki-filter-pills {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.wiki-pill-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-blue);
}

.wiki-pill-btn {
  padding: 5px 14px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.wiki-pill-btn:hover {
  background: var(--bg-card-hover);
  color: var(--text-primary);
  border-color: var(--accent-blue);
}

.wiki-pill-btn.active {
  background: #0284c7;
  border-color: #38bdf8;
  color: #ffffff;
  font-weight: 700;
}

/*  主技能卡片網格 */
.wiki-skills-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 12px;
}

.wiki-skill-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 12px 14px;
