  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.skill-name-text {
  font-size: 14.5px;
  font-weight: 700;
  color: var(--text-main);
  margin: 0;
  line-height: 1.2;
}

.skill-cat-tag {
  font-size: 10px;
  font-weight: 600;
