}

.skill-cat-tag.cat-energy { background: rgba(245, 158, 11, 0.2); color: #fbbf24; }
.skill-cat-tag.cat-energy_heal { background: rgba(236, 72, 153, 0.2); color: #f472b6; }
.skill-cat-tag.cat-ingredient { background: rgba(16, 185, 129, 0.2); color: #34d399; }
.skill-cat-tag.cat-special { background: rgba(139, 92, 246, 0.2); color: #a78bfa; }
.skill-cat-tag.cat-shards { background: rgba(56, 189, 248, 0.2); color: #38bdf8; }

[data-theme="dawn"] .skill-cat-tag.cat-energy { background: #fef3c7; color: #b45309; border: 1px solid #fde68a; }
[data-theme="dawn"] .skill-cat-tag.cat-energy_heal { background: #fce7f3; color: #be185d; border: 1px solid #fbcfe8; }
[data-theme="dawn"] .skill-cat-tag.cat-ingredient { background: #d1fae5; color: #047857; border: 1px solid #a7f3d0; }
[data-theme="dawn"] .skill-cat-tag.cat-special { background: #ede9fe; color: #6d28d9; border: 1px solid #ddd6fe; }
[data-theme="dawn"] .skill-cat-tag.cat-shards { background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; }

[data-theme="emerald"] .skill-cat-tag.cat-energy { background: #fef9c3; color: #854d0e; border: 1px solid #fde047; }
[data-theme="emerald"] .skill-cat-tag.cat-energy_heal { background: #fce7f3; color: #9d174d; border: 1px solid #fbcfe8; }
[data-theme="emerald"] .skill-cat-tag.cat-ingredient { background: #dcfce7; color: #15803d; border: 1px solid #86efac; }
[data-theme="emerald"] .skill-cat-tag.cat-special { background: #ede9fe; color: #5b21b6; border: 1px solid #ddd6fe; }
[data-theme="emerald"] .skill-cat-tag.cat-shards { background: #e0f2fe; color: #075985; border: 1px solid #bae6fd; }

.skill-max-lv-badge {
  font-size: 10.5px;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
  padding: 2px 7px;
  border-radius: 10px;
  white-space: nowrap;
  flex-shrink: 0;
}

[data-theme="dawn"] .skill-max-lv-badge,
[data-theme="emerald"] .skill-max-lv-badge {
  background: var(--bg-card-inner-subtle);
  border: 1px solid var(--border-color-subtle);
}

.skill-desc-text {
