  flex-direction: column;
  gap: 12px;
  justify-content: center;
}

.calc-form-row {
  display: flex;
  gap: 12px;
  align-items: flex-end;
}

.calc-field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 0%;
  min-width: 0;
