/*  食材天梯榜 - 寶可夢節點浮窗 (Pokemon Node Tooltip) */
.ladder-node-tooltip {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  background: #0d1527 !important;
  border: 1px solid rgba(255, 255, 255, 0.22) !important;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 11px;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: none !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  z-index: 999999;
  display: flex;
  flex-direction: column;
  gap: 2.5px;
  color: var(--text-primary);
  max-width: min(280px, calc(100vw - 32px)) !important;
}

/* 智能水平對齊 (左、中、右) */
.ladder-node.align-right .ladder-node-tooltip {
  left: auto !important;
  right: -8px !important;
  transform: none !important;
}

.ladder-node.align-left .ladder-node-tooltip {
  left: -8px !important;
  right: auto !important;
  transform: none !important;
}

.ladder-node.align-center .ladder-node-tooltip {
  left: 50% !important;
  right: auto !important;
  transform: translateX(-50%) !important;
}

/* 頂部前 5 行軌道：浮窗改為向下展開，保證永遠在最高層且不被頂部卡片/標題欄遮蔽裁切 */
.ladder-node.popup-down .ladder-node-tooltip,
.ladder-track-top .ladder-node-tooltip,
.ladder-track-row:nth-child(-n+6) .ladder-node-tooltip {
  bottom: auto !important;
  top: calc(100% + 6px) !important;
}

.ladder-node.popup-down.align-right .ladder-node-tooltip,
.ladder-track-top .ladder-node.align-right .ladder-node-tooltip,
.ladder-track-row:nth-child(-n+6) .ladder-node.align-right .ladder-node-tooltip {
  bottom: auto !important;
  top: calc(100% + 6px) !important;
  left: auto !important;
  right: -8px !important;
  transform: none !important;
}

.ladder-node.popup-down.align-left .ladder-node-tooltip,
.ladder-track-top .ladder-node.align-left .ladder-node-tooltip,
.ladder-track-row:nth-child(-n+6) .ladder-node.align-left .ladder-node-tooltip {
  bottom: auto !important;
  top: calc(100% + 6px) !important;
  left: -8px !important;
  right: auto !important;
  transform: none !important;
}

.ladder-node.popup-down.align-center .ladder-node-tooltip,
.ladder-track-top .ladder-node.align-center .ladder-node-tooltip,
.ladder-track-row:nth-child(-n+6) .ladder-node.align-center .ladder-node-tooltip {
  bottom: auto !important;
  top: calc(100% + 6px) !important;
  left: 50% !important;
  right: auto !important;
  transform: translateX(-50%) !important;
}

@media (hover: hover) and (pointer: fine) {
  .ladder-node:hover .ladder-node-tooltip,
  .ladder-node:active .ladder-node-tooltip {
    opacity: 1 !important;
    visibility: visible !important;
    pointer-events: auto !important;
  }
}

