}

.appraisal-summary-label {
  position: absolute;
  top: -8.5px;
  left: 12px;
  background: #0284c7;
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 800;
  line-height: 1.2;
  padding: 1px 8px;
  border-radius: 9999px;
