  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0;
  width: 100%;
  box-sizing: border-box;
}

.appraisal-pros-list,
.appraisal-cons-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 6px;
  width: 100%;
  box-sizing: border-box;
}

.appraisal-pro-item {
  font-size: 12px;
  color: var(--text-primary);
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid rgba(16, 185, 129, 0.22);
  padding: 7px 12px;
  border-radius: 8px;
  line-height: 1.45;
  box-sizing: border-box;
  width: 100%;
}

.appraisal-con-item {
  font-size: 12px;
