}

/* ═══════════════════════════════════════════════════════════════
    獨立評測實驗室 (Appraisal Lab)
   ═══════════════════════════════════════════════════════════════ */
.appraisal-lab-card,
.appraisal-lab-seamless-view {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0;
  box-shadow: none;
  width: 100%;
}

.appraisal-lab-header {
  display: none;
}

.appraisal-lab-layout {
  display: grid;
  grid-template-columns: minmax(300px, 360px) 1fr;
  gap: 20px;
  margin-top: 10px;
}

.appraisal-lab-layout.lab-preview-only-layout {
  grid-template-columns: 1fr !important;
}

.lab-preview-fullwidth {
  width: 100% !important;
  max-width: 100% !important;
}

.appraisal-lab-controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0;
}

.lab-control-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
