/* 評測實驗室 倉庫連動選取樣式 */
.lab-box-linkage-group {
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-color-subtle, rgba(255,255,255,0.08));
  margin-bottom: 2px;
}

.lab-box-reset-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 4px;
