}

.lab-box-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  color: var(--text-secondary);
  font-size: 11.5px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.lab-box-chip:hover {
  border-color: var(--accent-blue);
  color: var(--text-primary);
}

.lab-box-chip.active {
  background: rgba(56, 189, 248, 0.15);
  border-color: var(--accent-blue);
  color: var(--accent-blue);
  font-weight: 700;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.25);
}

.lab-box-chip-icon {
  width: 18px;
  height: 18px;
  object-fit: contain;
  border-radius: 50%;
}

.lab-box-chip-lv {
  font-size: 10px;
  padding: 1px 4px;
  border-radius: 4px;
  background: var(--bg-surface);
  color: var(--text-muted);
}

.lab-box-empty-hint {
  font-size: 11.5px;
  color: var(--text-muted);
  background: var(--bg-surface);
  border: 1px dashed var(--border-color);
  border-radius: 6px;
  padding: 8px 10px;
  margin-top: 4px;
  line-height: 1.4;
}

.lab-nickname-tag {
  font-size: 11px;
  font-weight: 700;
  background: rgba(147, 51, 234, 0.15);
  color: #c084fc;
  border: 1px solid rgba(147, 51, 234, 0.35);
  padding: 1px 7px;
  border-radius: 10px;
}

.lab-control-label {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-secondary);
}

.lab-select {
