  flex-direction: row !important;
  align-items: stretch;
  gap: 6px;
  background: transparent;
  border: none;
  padding: 0;
  margin-bottom: 10px;
  width: 100%;
}

.lab-compare-vs-player,
.lab-compare-vs-player.slot-a,
.lab-compare-vs-player.slot-b,
.lab-compare-vs-player.slot-c {
