}

.lab-compare-vs-player.slot-a { border-top: 3.5px solid #38bdf8; }
.lab-compare-vs-player.slot-b { border-top: 3.5px solid #c084fc; }
.lab-compare-vs-player.slot-c { border-top: 3.5px solid #f59e0b; }

.lab-compare-vs-header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-bottom: 2px;
}

.lab-compare-remove-btn {
