  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 2px 4px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.lab-compare-remove-btn:hover {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.15);
}

.lab-compare-empty-slot {
