  border-color: var(--accent-color, #38bdf8);
}

.lab-compare-empty-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  margin: auto 0;
}

.lab-compare-empty-plus {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-muted);
  line-height: 1;
}

.lab-compare-empty-text {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
}

.lab-compare-vs-divider {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0;
  flex-shrink: 0;
  width: 14px;
  z-index: 2;
}

.lab-compare-vs-badge {
  font-size: 9px;
  font-weight: 900;
  color: var(--text-primary);
  background: var(--bg-card-solid, #1e293b);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 999px;
