  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
}

.lab-compare-vs-avatar {
  width: 44px;
  height: 44px;
  object-fit: contain;
  border-radius: 50%;
}

.lab-compare-vs-lvl {
  position: absolute;
  bottom: -2px;
  right: -4px;
  font-size: 10px;
  font-weight: 800;
  padding: 0 5px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.85);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.4);
  line-height: 1.4;
  letter-spacing: -0.2px;
}

.lab-compare-pkm-name {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  text-align: center;
  line-height: 1.25;
  margin-top: 2px;
}

.lab-compare-micro-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-wrap: nowrap;
  max-width: 100%;
  margin-top: 2px;
}

.lab-compare-mini-berry {
  width: 13px;
  height: 13px;
  object-fit: contain;
  flex-shrink: 0;
}

.lab-compare-vs-tag.nat-tag {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-secondary);
  white-space: nowrap;
  max-width: 60px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.lab-compare-tap-hint {
  font-size: 9.5px;
  color: var(--text-muted);
  text-align: center;
  margin-top: 2px;
  opacity: 0.75;
}

/* 對比基準等級橫列 (Benchmark Row) */
.lab-compare-benchmark-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  flex-wrap: wrap;
}

.lab-compare-benchmark-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
}

.lab-compare-benchmark-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.benchmark-chip {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.benchmark-chip:hover {
  background: rgba(56, 189, 248, 0.1);
  color: var(--text-primary);
}

.benchmark-chip.active {
  background: var(--accent-color, #38bdf8) !important;
  color: #0f172a !important;
  border-color: transparent !important;
  font-weight: 800;
}

.lab-subskill-pill {
  display: inline-block;
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 5px;
  line-height: 1.3;
  text-align: center;
  max-width: 100%;
  word-break: break-all;
}

.lab-subskill-pill.locked {
  opacity: 0.42;
  filter: grayscale(60%);
}

.lab-grade-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 4px;
}

.lab-compare-vs-info,
.lab-compare-vs-player.slot-b .lab-compare-vs-info {
  justify-content: center;
  gap: 5px;
}

/* 選手標籤 (Slot Letter Badge) */
.lab-compare-slot-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
  color: #0f172a;
  padding: 1px 6px;
  border-radius: 4px;
  letter-spacing: 0.3px;
  line-height: 1.3;
}

.lab-compare-slot-letter.small {
  width: 18px;
  height: 18px;
  padding: 0;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 900;
  flex-shrink: 0;
}

/* 多選手長條圖 (Multi-Player Bar Rows) */
.lab-cmp-bar-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0;
}

.lab-cmp-bar-track {
  flex: 1;
  height: 8px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 999px;
  overflow: hidden;
  position: relative;
}

.lab-cmp-bar-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.3s ease;
}

.lab-cmp-bar-val {
  min-width: 85px;
  text-align: right;
  font-size: 12px;
  font-weight: 800;
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 多選手規格與效能對照表 (Multi-Player Spec & Performance Table) */
.lab-cmp-table {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
  border-top: 1px solid var(--border-color-subtle, rgba(255, 255, 255, 0.06));
}

.lab-cmp-row {
  display: grid;
  grid-template-columns: 140px repeat(var(--n, 2), 1fr);
  align-items: center;
  padding: 7px 8px;
  font-size: 12px;
  border-bottom: 1px solid var(--border-color-subtle, rgba(255, 255, 255, 0.04));
}

.lab-cmp-row:nth-child(even) {
  background: rgba(255, 255, 255, 0.015);
}

.lab-cmp-row.lab-cmp-head {
  padding: 8px 8px 6px;
  font-weight: 800;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.lab-cmp-label {
  color: var(--text-secondary);
  font-weight: 600;
}

.lab-cmp-val {
  text-align: center;
  font-weight: 700;
  color: var(--text-primary);
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
}

.lab-cmp-val.best {
  color: var(--pc, var(--accent-color, #38bdf8));
  font-weight: 900;
}

.lab-compare-empty-section-hint {
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
  padding: 16px 12px;
}

@media (max-width: 640px) {
  .lab-compare-vs-header {
    display: flex !important;
    flex-direction: row !important;
    gap: 4px !important;
  }
  .lab-compare-vs-player {
    padding: 6px 3px 8px;
    gap: 3px;
    border-radius: 10px;
  }
  .lab-compare-empty-slot {
    min-height: 105px;
    padding: 6px 3px;
  }
  .lab-compare-vs-avatar-wrap {
    width: 36px;
