  }
  .lab-compare-vs-divider {
    width: 10px;
  }
  .lab-compare-vs-badge {
    width: 18px;
    height: 18px;
    font-size: 8px;
  }
  .lab-cmp-row {
    grid-template-columns: 88px repeat(var(--n, 2), 1fr) !important;
    font-size: 10.5px !important;
    padding: 6px 3px !important;
  }
  .lab-cmp-label {
    font-size: 10.5px !important;
    padding-left: 3px !important;
  }
  .lab-cmp-val {
    font-size: 10.5px !important;
  }
  .lab-compare-benchmark-row {
    padding: 6px 8px;
    gap: 6px;
  }
  .lab-compare-benchmark-title {
    font-size: 11px;
  }
  .benchmark-chip {
    font-size: 10.5px;
    padding: 2px 7px;
  }
  .lab-subskill-pill {
    font-size: 9px;
    padding: 1px 3px;
  }
}

/* ═══ 選手/隊員挑選視窗：多欄卡片格線 ═══ */
.lab-picker-container { max-width: 880px; }

.lab-picker-search-bar {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.lab-picker-filter-chips button.active {
  background: var(--accent-color, #38bdf8) !important;
  color: #0f172a !important;
  border-color: transparent !important;
  font-weight: 700;
}

.lab-picker-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
