}

.lab-picker-avatar { position: relative; flex-shrink: 0; }
.lab-picker-avatar img { width: 52px; height: 52px; object-fit: contain; display: block; }

.lab-picker-lv {
  position: absolute;
  bottom: -2px;
  right: -8px;
