  overflow: hidden;
  text-overflow: ellipsis;
}

.lab-picker-nick {
  font-size: 10.5px;
  color: var(--accent-color, #38bdf8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
