/* ═══════════════════════════════════════════════════════════════
    多圖批次智能辨識 (Batch OCR Progress & Floating Toast)
   ═══════════════════════════════════════════════════════════════ */
.batch-ocr-progress-card {
  width: 100%;
  max-width: 520px;
  background: var(--bg-card-solid);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 14px 18px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.batch-ocr-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.batch-ocr-title {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--accent-blue);
}

.batch-ocr-counter {
  font-size: 12px;
  font-weight: 700;
  color: #fbbf24;
  background: rgba(245, 158, 11, 0.15);
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.batch-ocr-bar-bg {
  width: 100%;
  height: 8px;
  background: var(--bg-card-inner);
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border-color-subtle);
}

.batch-ocr-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #a855f7);
  border-radius: 6px;
  transition: width 0.25s ease;
}

.batch-ocr-status-text {
  font-size: 11.5px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 倉庫與雲端浮動 Toast 系統 */
.box-toast-container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 9999999;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}

@media (max-width: 768px) {
  .box-toast-container {
    bottom: calc(72px + env(safe-area-inset-bottom, 0px));
    right: 14px;
    left: 14px;
    align-items: center;
  }
  .box-toast-item {
    min-width: 0 !important;
    width: 100% !important;
    max-width: 420px !important;
  }
}

.box-toast-item {
  pointer-events: auto;
  min-width: 320px;
  max-width: 440px;
