}

.box-toast-item.toast-error {
  border-color: rgba(239, 68, 68, 0.45);
  border-left: 4px solid #ef4444;
}

.box-toast-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  margin-top: 2px;
  flex-shrink: 0;
}

.box-toast-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.box-toast-title {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
}

.box-toast-msg {
  font-size: 11.5px;
