  left: 0;
  right: 0;
  height: calc(62px + env(safe-area-inset-bottom, 0px));
  max-height: calc(62px + env(safe-area-inset-bottom, 0px));
  box-sizing: border-box;
  z-index: 1000;
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: var(--bg-header);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid var(--border-color);
  padding-top: 4px;
  padding-bottom: calc(4px + env(safe-area-inset-bottom, 0px));
  box-shadow: 0 -1px 4px rgba(0, 0, 0, 0.12);
  user-select: none;
  -webkit-user-select: none;
}

.dock-tab,
.dock-tab-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 48px;
  padding: 4px 0;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  position: relative;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
  outline: none;
}

.dock-tab:active,
.dock-tab-btn:active {
  transform: scale(0.92);
}

.dock-tab .dock-icon,
.dock-tab-btn .dock-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  width: 24px;
  font-size: 19px;
  line-height: 1;
  color: var(--text-muted);
  transition: transform 0.2s ease, color 0.2s ease, filter 0.2s ease;
}

.dock-tab .dock-icon svg,
.dock-tab .dock-svg {
  width: 22px;
  height: 22px;
  stroke: var(--text-muted);
  transition: stroke 0.2s ease, transform 0.2s ease;
}

.dock-tab .dock-label,
.dock-tab-btn .dock-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.3px;
  line-height: 1.2;
  transition: color 0.2s ease;
}

/* Active 狀態發光與頂部指示線 */
.dock-tab.active,
.dock-tab-btn.active {
  color: var(--accent-color);
}

.dock-tab.active .dock-icon,
.dock-tab-btn.active .dock-icon {
  transform: translateY(-1px);
  color: var(--accent-blue, #38bdf8);
}

.dock-tab.active .dock-icon svg,
.dock-tab.active .dock-svg {
  stroke: var(--accent-blue, #38bdf8);
  filter: none;
}

.dock-tab.active .dock-label,
.dock-tab-btn.active .dock-label {
  color: var(--accent-color);
  font-weight: 700;
  text-shadow: none;
}

.dock-tab::after,
.dock-tab-btn::after {
  content: '';
  position: absolute;
  top: -6px;
  width: 0;
  height: 2.5px;
  background: var(--accent-color);
  border-radius: 0 0 3px 3px;
  box-shadow: none;
  transition: width 0.2s ease;
}

.dock-tab.active::after,
.dock-tab-btn.active::after {
  width: 32px;
}

