/* =========================================================
   回到頂部浮動按鈕 (Back to Top Floating Button)
   通用於桌面網頁版與行動端 H5 App，具備絲滑淡入淡出與避讓邏輯
   ========================================================= */
.back-to-top-btn {
  position: fixed;
  right: 28px;
  bottom: 32px;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--bg-card, #1e293b);
  color: var(--text-primary, #ffffff);
  border: 1.5px solid var(--border-color, rgba(255, 255, 255, 0.18));
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.28);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 990;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(12px) scale(0.92);
  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              visibility 0.25s,
              background-color 0.2s ease,
              border-color 0.2s ease,
              bottom 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
  outline: none;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.back-to-top-btn.visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

.back-to-top-btn:hover {
  background: var(--bg-sidebar-btn-hover, #334155);
  border-color: var(--accent-blue, #38bdf8);
  color: var(--accent-blue, #38bdf8);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
  transform: translateY(-2px) scale(1.04);
}

.back-to-top-btn:active {
  transform: translateY(0) scale(0.94);
}

.back-to-top-icon {
  width: 22px;
  height: 22px;
  stroke: currentColor;
  display: block;
  transition: transform 0.2s ease;
}

.back-to-top-btn:hover .back-to-top-icon {
  transform: translateY(-2px);
}

/* 主題適配 (Theme Adaptations) */
[data-theme="onyx"] .back-to-top-btn {
  background: rgba(18, 18, 18, 0.92);
  border-color: rgba(255, 255, 255, 0.16);
  color: #f8fafc;
}

[data-theme="dawn"]:not([data-theme-inverted="true"]) .back-to-top-btn {
  background: rgba(255, 255, 255, 0.95);
  border-color: rgba(0, 0, 0, 0.12);
  color: #1e293b;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
}

[data-theme="emerald"]:not([data-theme-inverted="true"]) .back-to-top-btn {
