/* 錨定於滑桿軌道之重點等級圖釘容器 */
.pokedex-anchored-slider-wrap {
  position: relative;
  width: 100%;
  padding-top: 4px;
  padding-bottom: 20px;
  display: flex;
  flex-direction: column;
}

.pokedex-slider-track-wrap {
  position: relative;
  width: 100%;
  height: 20px;
  display: flex;
  align-items: center;
}

.pokedex-slider-track-bar {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.18);
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}

/* 等級滾動條隨數值填滿條 (Fill Progress Bar) */
.pokedex-slider-fill-bar {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: #38bdf8;
  border-radius: 3px 0 0 3px;
  pointer-events: none;
  z-index: 1;
  transition: width 0.05s ease;
}

/* 最低進化門檻限制之紅色禁區 (置於進度條上方圖層 z-index: 2，確保不可滑動區間醒目可見) */
.pokedex-slider-locked-zone {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    -45deg,
    #ef4444,
    #ef4444 5px,
    #dc2626 5px,
    #dc2626 10px
  );
  border-right: 2.5px solid #b91c1c;
  box-shadow: 0 0 8px rgba(239, 68, 68, 0.7);
  pointer-events: none;
  z-index: 2;
  transition: filter 0.15s ease, box-shadow 0.15s ease;
}

.pokedex-slider-locked-edge {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: #ffffff;
  opacity: 0.9;
}

.pokedex-slider-locked-zone.locked-bounce {
  animation: lockedBounceAnim 0.35s ease;
}

@keyframes lockedBounceAnim {
  0% { filter: brightness(1); box-shadow: 0 0 8px rgba(239, 68, 68, 0.7); }
  50% { filter: brightness(1.6); box-shadow: 0 0 16px rgba(239, 68, 68, 1); }
  100% { filter: brightness(1); box-shadow: 0 0 8px rgba(239, 68, 68, 0.7); }
}

.pokedex-slider {
  position: relative;
  width: 100%;
  height: 6px;
  background: transparent;
  accent-color: var(--accent-blue, #38bdf8);
  cursor: pointer;
  z-index: 2;
  margin: 0;
  -webkit-appearance: none;
  appearance: none;
}

.pokedex-slider::-webkit-slider-runnable-track {
  background: transparent;
  height: 6px;
}

.pokedex-slider::-moz-range-track {
  background: transparent;
  height: 6px;
}

.pokedex-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #38bdf8;
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
  cursor: pointer;
  margin-top: -5px;
