  box-sizing: border-box;
}

.wiki-item-modal-header {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  background: var(--bg-card-solid);
}

.wiki-item-modal-title-group {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.wiki-item-modal-icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: var(--bg-card-inner);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 4px;
  box-sizing: border-box;
}

.wiki-item-modal-icon {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.wiki-item-modal-heading {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.wiki-item-modal-title-row {
